import{_ as d,c as f,s as p,o as t}from"./index-CqPiz6kj.js";const e={},v={class:"privacy-page"};function o(c,a){return t(),f("div",v,[...a[0]||(a[0]=[p('<div class="container" data-v-efd3fa94><div class="privacy-card" data-v-efd3fa94><h1 data-v-efd3fa94>隐私政策</h1><p class="update-time" data-v-efd3fa94>更新日期：2026年9月1日</p><div class="privacy-content" data-v-efd3fa94><h2 data-v-efd3fa94>一、引言</h2><p data-v-efd3fa94>TLLOS商城（以下简称&quot;本平台&quot;）深知个人信息对您的重要性，我们将按照法律法规要求，采取相应的安全保护措施，致力于保护您的个人信息安全可控。</p><p data-v-efd3fa94>本隐私政策将帮助您了解：我们如何收集、使用、存储和保护您的个人信息，以及您享有的相关权利。请您在使用本平台服务前，仔细阅读并充分理解本政策全部内容。</p><h2 data-v-efd3fa94>二、我们收集的信息</h2><h3 data-v-efd3fa94>2.1 您主动提供的信息</h3><p data-v-efd3fa94>（1）账户注册信息：手机号、密码、昵称、头像等；</p><p data-v-efd3fa94>（2）实名认证信息：真实姓名、身份证号等（如需）；</p><p data-v-efd3fa94>（3）收货地址信息：收货人姓名、手机号、详细地址等；</p><p data-v-efd3fa94>（4）支付信息：支付账户、交易记录等；</p><p data-v-efd3fa94>（5）售后信息：售后申请、退换货记录等。</p><h3 data-v-efd3fa94>2.2 我们自动收集的信息</h3><p data-v-efd3fa94>（1）设备信息：设备型号、操作系统、设备标识符等；</p><p data-v-efd3fa94>（2）日志信息：浏览记录、搜索记录、点击记录、访问时间等；</p><p data-v-efd3fa94>（3）位置信息：经纬度信息（需您授权）；</p><p data-v-efd3fa94>（4）Cookie信息：用于识别您的身份、保存您的偏好设置。</p><h2 data-v-efd3fa94>三、我们如何使用信息</h2><p data-v-efd3fa94>3.1 为您提供商品和服务：包括账户管理、订单处理、商品配送、售后服务等；</p><p data-v-efd3fa94>3.2 为您推荐个性化内容：基于您的浏览和购买记录，为您推荐可能感兴趣的商品；</p><p data-v-efd3fa94>3.3 保障账户和交易安全：识别异常登录、防范欺诈行为、验证您的身份；</p><p data-v-efd3fa94>3.4 改进产品和服务：分析用户行为数据，优化平台功能和用户体验；</p><p data-v-efd3fa94>3.5 遵守法律法规要求：配合监管部门、司法机关的调查和取证。</p><h2 data-v-efd3fa94>四、信息的共享与披露</h2><p data-v-efd3fa94>4.1 我们不会向第三方出售您的个人信息。</p><p data-v-efd3fa94>4.2 在以下情况下，我们可能会共享您的个人信息：</p><p data-v-efd3fa94>（1）为完成交易必需：向商家、物流公司、支付机构提供必要的订单和配送信息；</p><p data-v-efd3fa94>（2）获得您的明确同意：在您授权的情况下与第三方共享；</p><p data-v-efd3fa94>（3）法律法规要求：根据法律法规、诉讼程序、政府主管部门的强制性要求；</p><p data-v-efd3fa94>（4）保护合法权益：在紧急情况下，为保护本平台、用户或公众的合法权益。</p><h2 data-v-efd3fa94>五、信息的存储与保护</h2><p data-v-efd3fa94>5.1 存储地点：您的个人信息将存储在中华人民共和国境内的服务器上。</p><p data-v-efd3fa94>5.2 存储期限：我们仅在实现服务目的所必需的最短期限内保留您的个人信息，超出期限后将删除或匿名化处理。</p><p data-v-efd3fa94>5.3 安全措施：我们采用加密传输、访问控制、数据脱敏等技术手段保护您的个人信息安全，并建立完善的信息安全管理制度。</p><p data-v-efd3fa94>5.4 安全事件：如发生个人信息安全事件，我们将按照法律法规要求及时通知您，并采取补救措施。</p><h2 data-v-efd3fa94>六、您的权利</h2><p data-v-efd3fa94>6.1 访问权：您有权访问您的个人信息，可在&quot;个人中心&quot;查看和管理您的账户信息。</p><p data-v-efd3fa94>6.2 更正权：您有权更正不准确的个人信息，可在&quot;个人中心&quot;修改您的资料。</p><p data-v-efd3fa94>6.3 删除权：在符合法律法规的前提下，您有权要求删除您的个人信息。</p><p data-v-efd3fa94>6.4 撤回同意权：您有权撤回之前给予的授权同意，但撤回同意不影响此前基于同意进行的信息处理。</p><p data-v-efd3fa94>6.5 注销账户权：您有权注销您的账户，注销后我们将删除或匿名化处理您的个人信息。</p><p data-v-efd3fa94>6.6 投诉举报权：您有权对我们处理个人信息的行为进行投诉举报。</p><h2 data-v-efd3fa94>七、未成年人保护</h2><p data-v-efd3fa94>7.1 本平台主要面向成年人。如您为未成年人，请在监护人的指导下阅读本政策并使用本平台服务。</p><p data-v-efd3fa94>7.2 我们不会主动收集未成年人的个人信息。如发现未成年人在未获得监护人同意的情况下使用本平台服务，我们将尽快删除相关信息。</p><h2 data-v-efd3fa94>八、Cookie的使用</h2><p data-v-efd3fa94>8.1 我们使用Cookie和类似技术来识别您的身份、保存您的偏好设置、提升用户体验。</p><p data-v-efd3fa94>8.2 您可以通过浏览器设置管理或删除Cookie，但禁用Cookie可能影响您使用本平台的部分功能。</p><h2 data-v-efd3fa94>九、本政策的更新</h2><p data-v-efd3fa94>9.1 我们可能根据业务发展或法律法规变化适时更新本隐私政策。</p><p data-v-efd3fa94>9.2 政策更新后，我们将在平台公布最新版本。如更新涉及您个人信息处理的重大变化，我们将通过显著方式通知您。</p><p data-v-efd3fa94>9.3 您继续使用本平台服务，即视为同意接受更新后的隐私政策。</p><h2 data-v-efd3fa94>十、联系我们</h2><p data-v-efd3fa94>如您对本隐私政策有任何疑问、意见或建议，可通过以下方式联系我们：</p><p data-v-efd3fa94>客服热线：400-888-8888</p><p data-v-efd3fa94>电子邮箱：privacy@tllos.com</p><p data-v-efd3fa94>我们将在收到您的反馈后15个工作日内予以回复。</p></div></div></div>',1)])])}const s=d(e,[["render",o],["__scopeId","data-v-efd3fa94"]]);export{s as default};
